  const FLASH = [
    { id: 'c15-01', kind: 'concepto', q: '¿Por dónde abres el caso de CTR de anuncios y por qué no por el modelo?',
      a: 'Por el <b>flujo del dinero</b>: el anunciante paga por clic, así que se ordena por <b>eCPM = bid × pCTR × 1000</b>, y el precio por clic también sale del pCTR. Eso exige probabilidades calibradas. Después, ubicar el ad server en la página: 50 ms, y el contenido nunca espera.' },
    { id: 'c15-02', kind: 'numero', q: 'Tráfico y candidatos del caso.',
      a: '12 M usuarios × 8 páginas ≈ 100 M páginas/día → ≈ 1,160 RPS; pico diario ≈ 3,500; <b>6,000 RPS</b> de diseño (noticia). ≈ 2,500 anuncios → ≈ 150 elegibles → <b>900k scores/s</b> en el pico.' },
    { id: 'c15-03', kind: 'numero', q: 'CPU del ad-api en el pico de diseño.',
      a: '6,000 × ≈ 8 ms = <b>48 vCPU</b> ocupadas; al 50 % → 96 → 6 × c7i.4xlarge (16 vCPU) + 1 = <b>7</b>. Fuera de pico ≈ 3. ≈ US$2.5–3.6k/mes.' },
    { id: 'c15-04', kind: 'numero', q: 'Impresiones, clics e ingreso.',
      a: '≈ 300 M impresiones/día, CTR ≈ 0.35 % → ≈ <b>1.05 M clics/día</b>. RPM ≈ US$2.5 → ≈ US$250k/día ≈ <b>US$7.5 M/mes</b>; <b>1 % de RPM ≈ US$75k/mes</b>; precio medio ≈ US$0.24 por clic.' },
    { id: 'c15-05', kind: 'concepto', q: 'Regla de precio del caso (GSP).',
      a: 'Gana el mayor eCPM sobre la reserva (US$0.80), slot por slot, del más valioso al menos valioso. Paga por clic: <b>max(eCPM del siguiente, reserva) ÷ (1000 × su pCTR) + US$0.01</b>, con tope en su bid. Un anuncio por anunciante en la página; empates con un hash del request, reproducibles.' },
    { id: 'c15-06', kind: 'trampa', q: 'A (bid 0.50, pCTR 0.60 %) le gana a B (bid 1.20, pCTR 0.20 %). ¿Qué pasa si el pCTR de A está sobreestimado 25 %?',
      a: 'Sigue ganando (mismo orden, mismo AUC), pero paga 2.40 ÷ (1000 × 0.0075) + 0.01 = <b>US$0.33</b> en vez de US$0.41: <b>−20 %</b> de ingreso. Subestimado 10 %, paga US$0.454: un sobrecobro de 11 %.' },
    { id: 'c15-07', kind: 'concepto', q: '¿Por qué el AUC no alcanza en ads?',
      a: 'Es invariante a la calibración: multiplicar todos los pCTR × 2 deja el AUC igual. Pero el precio tiene el pCTR del ganador en el denominador, y la reserva compara eCPM absolutos. Gate: NE mejor y calibración 0.9–1.1 por slice; el AUC, solo como sanidad.' },
    { id: 'c15-08', kind: 'numero', q: 'NE con el CTR del caso.',
      a: 'Entropía del CTR de fondo 0.35 %: −(0.0035 ln 0.0035 + 0.9965 ln 0.9965) ≈ <b>0.02329</b> nats. Log loss del modelo 0.0210 → <b>NE ≈ 0.902</b> (≈ 10 % mejor que predecir el promedio). Menor es mejor.' },
    { id: 'c15-09', kind: 'numero', q: 'Submuestreo al 5 %: filas y corrección.',
      a: '1.05 M clics + 5 % de ≈ 299 M no-clics ≈ <b>16 M filas/día</b> (≈ 224 M en 14 días). Con CTR real 0.35 %, el training set tiene ≈ 6.56 %; <b>q = p / (p + (1 − p)/w)</b> devuelve 0.35 %. Olvidarla infla el eCPM ≈ 19×.' },
    { id: 'c15-10', kind: 'trampa', q: 'Entrenas con peso 1/w en los negativos y además aplicas q = p / (p + (1 − p)/w). ¿Qué pasa?',
      a: 'Corriges dos veces: el modelo ya sale en escala real y la fórmula lo baja otra vez, ≈ 20× (1/w) por debajo con w = 5 %. Una sola corrección, y el w guardado en cada fila.' },
    { id: 'c15-11', kind: 'concepto', q: '¿Qué es una impresión en este caso y por qué importa para el label?',
      a: 'Una impresión <b>viewable</b> (display, IAB/MRC: ≥ 50 % de los pixeles en pantalla ≥ 1 s continuo), con beacon y token. Label: clic dentro de 30 min. Un anuncio que nadie vio no es un “no clic”: contarlo hunde el CTR del slot de abajo por el scroll, no por el anuncio.' },
    { id: 'c15-12', kind: 'concepto', q: '¿Para qué sirve el token de impresión firmado?',
      a: 'Une decisión, beacon y clic sin adivinar; lleva firmados (HMAC) el precio calculado en la subasta, el pCTR, el slot y el origen (model, explore o fallback); un token inválido o vencido no se cobra. Firmado no es cifrado: el precio se ve en la URL. Es la llave del training set, de la facturación y de cualquier reclamo.' },
    { id: 'c15-13', kind: 'trampa', q: 'Features que parecen buenas y son leakage en CTR.',
      a: 'Tiempo visible del anuncio, profundidad de scroll, si la persona volvió a la página, el CTR “de hoy” del anuncio calculado al final del día: no existen cuando ad-api decide. El modelo solo ve el snapshot de la decisión.' },
    { id: 'c15-14', kind: 'concepto', q: 'Sesgo de posición: la solución del caso.',
      a: 'Slot (y slot × formato) como feature en training, en índices reservados del hashing. Al servir, un scoring por candidato sin posición y cada slot suma su término aprendido: el pCTR exacto de cada slot en un solo pase (con la LR, y con el DNN si la posición entra solo como término aditivo del logit; supone efecto del anuncio × efecto de la posición, como Varian 2007). La exploración lo verifica. Alternativa: un modelo de posición aparte que se apaga al servir (PAL).' },
    { id: 'c15-15', kind: 'concepto', q: 'Exploración: cuánto, para qué y cuánto cuesta.',
      a: '≈ 1 % de los requests asigna al azar entre los elegibles sobre la reserva, con propensity. Sirve para verificar los factores de posición, evaluación contrafactual por slot y anuncios nuevos. Si el azar rinde ≈ 70 % del RPM, cuesta ≈ 0.3 % del ingreso ≈ US$22k/mes.' },
    { id: 'c15-16', kind: 'tradeoff', q: 'Impulso para anuncios nuevos: ¿quién paga la exploración?',
      a: 'El medio. El impulso (primeras ≈ 10,000 impresiones, ≈ 35 clics esperados) multiplica solo la puntuación de ranking; el anuncio con impulso paga lo mínimo para conservar el lugar que le dio el impulso: menos que sin él. Si el siguiente tiene impulso, cuenta su eCPM real. En exploración aleatoria se paga lo de la reserva. Nunca más que en una subasta normal.' },
    { id: 'c15-17', kind: 'concepto', q: 'Topes de frecuencia: dónde viven y cuándo se cuentan.',
      a: 'En Redis, una llave por persona, campaña y día (<code>fc:{user}:campaña:día</code>, TTL 48 h); el hash tag <code>{user}</code> deja todas en un shard: un MGET por request. Se cuentan <b>al servir</b>, después de responder: la página puede pedir otra vez antes del beacon, y contar de más solo adelanta el tope. Sin consentimiento no hay id, ni topes.' },
    { id: 'c15-18', kind: 'concepto', q: 'Pacing de CPC: ¿por qué el gasto “llega tarde”?',
      a: 'El gasto ocurre en el clic, hasta 30 min después de la impresión (o más). El controlador compara gasto real + <b>gasto en riesgo</b> (Σ pCTR × precio de las impresiones recientes sin clic) contra la curva objetivo y ajusta el <b>serve_rate</b> (probabilidad de participar). Tope duro en ad-api, independiente del controlador: gasto ≥ presupuesto → fuera.' },
    { id: 'c15-19', kind: 'tradeoff', q: '¿Por qué no GPU para el scoring?',
      a: '900k scores/s de un modelo chico son ≈ 27 vCPU ocupadas. Dos L4 (N+1, dos zonas) costarían ≈ US$1.2k/mes, lo mismo que esa CPU, y agregan un salto de red, batching entre requests y una flota lenta para escalar en una noticia. Se reconsidera con 10× más modelo o más candidatos.' },
    { id: 'c15-20', kind: 'tradeoff', q: 'Hashing en 2^24 buckets: costo y riesgo.',
      a: '16.8 M pesos × 4 B ≈ 64 MiB por pod. Colisiones: 1 − e<sup>−n/m</sup> → con ≈ 10<sup>5</sup> features distintas activas, ≈ 0.6 %; con 10<sup>6</sup>, ≈ 6 %. Chocan sobre todo valores raros; la posición va en índices reservados, fuera del hash. Hash estable (blake2b), nunca el hash() de Python.' },
    { id: 'c15-21', kind: 'numero', q: 'Personas por brazo para detectar 1 % de RPM.',
      a: 'Con σ/μ = 3 (supuesto, mídelo): n = 2 × 7.85 × 9 ÷ 0.01² ≈ <b>1.41 M por brazo</b>; 2 % → ≈ 353k; 5 % → ≈ 57k. El RPM es un cociente: varianza por persona (delta method).' },
    { id: 'c15-22', kind: 'trampa', q: '¿Por qué un A/B normal de ads miente?',
      a: 'Los brazos comparten el presupuesto de cada campaña: el tratamiento agota las mejores campañas y el control pasa la tarde sin ellas (canibalización). <b>Budget-split</b>: el presupuesto de cada campaña se parte por brazo en proporción al tráfico, y cada pedazo tiene su propio pacing (LinkedIn, KDD 2021).' },
    { id: 'c15-23', kind: 'numero', q: 'Calibración por hora: ¿cuánto ruido?',
      a: '≈ 43,750 clics por hora → ruido relativo ≈ 1/√43,750 ≈ 0.5 %. Un slice con 200 clics esperados → ≈ 7 %: la banda de page (0.8–1.25) son ≈ 3σ; con 1,000 esperados → ≈ 3 %: la banda objetivo (0.9–1.1) también. Por eso las alertas piden volumen mínimo y duración.' },
    { id: 'c15-24', kind: 'concepto', q: 'Las 8 alertas del caso.',
      a: '<code>AdServerLatencyHigh</code>, <code>AdFallbackRateHigh</code>, <code>CalibrationRatioOff</code>, <code>CTRDrop</code>, <code>RPMDrop</code>, <code>UserFeatureStoreStale</code>, <code>AdEventLogLag</code> y <code>BudgetPacingOff</code>.' },
    { id: 'c15-25', kind: 'concepto', q: 'Escalera de degradación.',
      a: 'Modelo completo → solo contexto (sin features de persona) → bid × CTR suavizado por anuncio × slot → programático → house ads. El presupuesto no se degrada (tope duro en ad-api, fail-closed); los topes sí, unos minutos (fail-open). La página nunca espera.' },
    { id: 'c15-26', kind: 'tradeoff', q: 'Redis no contesta: ¿qué haces con los topes y qué con los presupuestos?',
      a: 'Topes: <b>fail-open</b>, se sirve sin topes mientras dure y se cuenta: en CPC una impresión de más no se cobra, y casi todas las campañas tienen tope (excluirlas mandaría la página al programático). Presupuestos: la última lectura de ≤ 60 s y después <b>fail-closed</b>: un clic más allá del presupuesto sí se cobra.' },
    { id: 'c15-27', kind: 'frase', q: '¿Cómo abres el caso en inglés?',
      a: '“Before designing anything, I’d like to follow the money: advertisers pay per click, so I rank by bid times predicted CTR, and the price per click depends on that prediction too. That means I need calibrated probabilities, not just a good ranking, within a few tens of milliseconds and without ever making the page wait.”' },
    { id: 'c15-28', kind: 'frase', q: '¿Cómo explicas en inglés por qué la calibración es un criterio de lanzamiento?',
      a: '“In a second-price auction the winner’s predicted CTR is in the denominator of its price, so a model can keep the same ranking and still undercharge or overcharge. That’s why the gate asks for better normalized entropy and a calibration ratio within ten percent per slice, and AUC is only a sanity check.”' },
  ];

  // --------------------------------------------------------------- glosario
  // Términos nuevos de ad tech, subastas y calibración. Los de experimentos genéricos
  // (MDE, SRM, CUPED, interleaving), streaming y feature store los definen M9–M12, c08 y c09.
  const GLOSS = [
    { en: 'click-through rate (CTR)', es: 'tasa de clics',
      def: 'Clics ÷ impresiones. En ads hay que decir sobre qué denominador (impresiones servidas o viewable): el mismo sistema da CTRs distintos según cuál uses.',
      say: 'Our average CTR is about a third of a percent on viewable impressions.' },
    { en: 'predicted CTR (pCTR)', es: 'CTR predicho',
      def: 'La probabilidad de clic que el modelo asigna a un anuncio en un contexto y un slot. Entra en el ranking (eCPM) y en el precio, así que tiene que estar calibrada.',
      say: 'The pCTR feeds both the ranking and the price, so we gate launches on calibration.' },
    { en: 'effective cost per mille (eCPM)', es: 'costo efectivo por mil impresiones',
      def: 'El valor esperado de 1,000 impresiones de un anuncio: bid × pCTR × 1000 para un anuncio CPC. Permite comparar anuncios CPC entre sí y contra la reserva.',
      say: 'We rank by eCPM, so a cheaper bid with twice the CTR can win.' },
    { en: 'revenue per mille (RPM)', es: 'ingreso por mil páginas vistas',
      def: 'Ingreso ÷ páginas vistas × 1000. Es la métrica de negocio del medio: junta precio, CTR y fill rate en un número.',
      say: 'The primary metric is RPM, with engagement and advertiser-cost guardrails.' },
    { en: 'cost per click (CPC)', es: 'costo por clic',
      def: 'Modelo de cobro en el que el anunciante paga solo cuando alguien hace clic; también, el precio pagado por cada clic.',
      say: 'Advertisers bid CPC, so we only bill valid clicks.' },
    { en: 'generalized second-price auction (GSP)', es: 'subasta de segundo precio generalizada',
      def: 'Subasta de varios slots en la que cada ganador paga lo mínimo para conservar su lugar: el eCPM del siguiente ÷ (1000 × su propio pCTR). No es truthful, pero es estable y fácil de explicar.',
      say: 'In our GSP auction, the winner’s pCTR is in the denominator of its price.' },
    { en: 'reserve price', es: 'precio de reserva',
      def: 'El eCPM mínimo para que un anuncio directo gane un slot; por debajo, el slot va a otra demanda (aquí, la programática). Representa el costo de oportunidad del slot.',
      say: 'Below the reserve eCPM, the slot goes to programmatic.' },
    { en: 'first-price auction', es: 'subasta de primer precio',
      def: 'El ganador paga lo que pujó. Es la regla de los exchanges programáticos hoy; los compradores responden bajando sus pujas automáticamente (bid shading).',
      say: 'Exchanges moved to first-price auctions, so buyers shade their bids.' },
    { en: 'frequency cap', es: 'tope de frecuencia',
      def: 'Máximo de impresiones de una campaña por persona en un periodo (p. ej. 5 al día). Es una promesa al anunciante y un filtro antes de puntuar.',
      say: 'Caps live in Redis, keyed by user, campaign and day, and are counted when we serve.' },
    { en: 'budget pacing', es: 'dosificación del presupuesto',
      def: 'Repartir el presupuesto diario de una campaña a lo largo del día para que no se agote en la primera hora ni quede sin gastar.',
      say: 'Pacing compares spend plus in-flight spend against a target curve every minute.' },
    { en: 'probabilistic throttling', es: 'limitación probabilística',
      def: 'Forma de pacing que ajusta la probabilidad de que una campaña participe en cada subasta (su serve_rate), sin tocar su bid.',
      say: 'We throttle participation with a serve rate, never the bid.' },
    { en: 'ad server', es: 'servidor de anuncios',
      def: 'El sistema que decide qué anuncio va en cada slot (segmentación, topes, presupuestos, subasta) y registra impresiones y clics.',
      say: 'Our ad server has a fifty-millisecond budget, and the page never waits for it.' },
    { en: 'fill rate', es: 'tasa de llenado',
      def: 'Fracción de slots que se llenan con un anuncio (de la demanda propia, o de cualquier demanda, según quién reporte). Sube o baja con la reserva.',
      say: 'Raising the reserve lifts prices but lowers our fill rate.' },
    { en: 'programmatic advertising', es: 'publicidad programática',
      def: 'Venta automatizada de impresiones a compradores externos en tiempo real (exchanges, header bidding). Aquí es el fallback para los slots que no ganan las campañas propias.',
      say: 'Programmatic fills whatever our direct campaigns don’t win.' },
    { en: 'house ad', es: 'anuncio propio',
      def: 'Anuncio del propio medio (suscripciones, newsletter) que llena un slot cuando no hay demanda pagada. No genera ingreso, pero evita un hueco.',
      say: 'House ads are the last rung of the degradation ladder.' },
    { en: 'viewable impression', es: 'impresión visible (viewable)',
      def: 'Impresión que cumple un criterio de visibilidad; para display, según IAB y el MRC, ≥ 50 % de los pixeles en pantalla durante ≥ 1 s continuo.',
      say: 'The label is a click within thirty minutes of a viewable impression.' },
    { en: 'impression token', es: 'token de impresión',
      def: 'Blob firmado que el ad server adjunta a cada anuncio servido (request, anuncio, campaña, slot, precio, pCTR, origen, hora); la página lo devuelve en el beacon y en el clic. Hace exacto el join y no se puede falsificar, aunque sí leer.',
      say: 'Every click carries the signed impression token, so we can replay its price.' },
    { en: 'click redirect', es: 'redirección de clic',
      def: 'Endpoint que registra el clic y redirige (302) a la página del anunciante. Está en el camino de la persona: espera el ack de Kafka solo un momento (aquí, hasta 200 ms) y, si no llega, redirige igual.',
      say: 'The click redirect waits at most two hundred milliseconds for the Kafka ack, then redirects anyway.' },
    { en: 'invalid traffic (IVT)', es: 'tráfico inválido',
      def: 'Impresiones y clics que no vienen de personas reales con intención. El MRC distingue el general (GIVT, filtrable con listas y reglas) del sofisticado (SIVT, que exige análisis avanzado).',
      say: 'Invalid clicks are excluded from billing and from training.' },
    { en: 'normalized entropy (NE)', es: 'entropía normalizada',
      def: 'Log loss promedio ÷ la entropía del CTR de fondo (el log loss de predecir el promedio para todo). Menor es mejor; 1 significa no superar al promedio.',
      say: 'The candidate improves normalized entropy by half a percent at the same calibration.' },
    { en: 'log loss', es: 'pérdida logarítmica',
      def: 'Promedio de −log de la probabilidad asignada a lo que de verdad pasó. Castiga las probabilidades seguras y equivocadas; mide orden y calibración juntos.',
      say: 'We train on log loss so the probabilities stay meaningful.' },
    { en: 'calibration ratio', es: 'cociente de calibración',
      def: 'Clics observados ÷ clics esperados (Σ pCTR) en un periodo y un slice; 1 es perfecto. Algunos papers lo definen al revés (esperados ÷ observados): di cuál usas.',
      say: 'The hourly calibration ratio must stay between 0.9 and 1.1 per slice.' },
    { en: 'reliability diagram', es: 'diagrama de confiabilidad',
      def: 'Gráfico de la probabilidad predicha media contra la frecuencia observada, por bin. Muestra dónde se descalibra un modelo.',
      say: 'The reliability diagram shows the top bucket overpredicting by eighteen percent.' },
    { en: 'downsampling correction', es: 'corrección del submuestreo',
      def: 'Fórmula que devuelve a escala real la predicción de un modelo entrenado con negativos submuestreados a tasa w: q = p / (p + (1 − p)/w).',
      say: 'We apply the downsampling correction with the rate stored in each row.' },
    { en: 'feature hashing', es: 'hashing de features',
      def: 'Mapear cada feature (o cruce) a un índice con una función hash, en un espacio de tamaño fijo y sin vocabulario. Ahorra memoria y mantenimiento a cambio de colisiones.',
      say: 'Feature hashing into two to the twenty-fourth buckets keeps the model at sixty-seven megabytes.' },
    { en: 'feature cross', es: 'cruce de features',
      def: 'Feature que combina dos o más (sección × categoría del anuncio) para que un modelo lineal capture su interacción.',
      say: 'Section times ad category is our strongest cross.' },
    { en: 'embedding table', es: 'tabla de embeddings',
      def: 'Matriz con un vector aprendido por valor de una feature categórica (o por bucket de hashing). En modelos de CTR suele concentrar casi todos los parámetros.',
      say: 'Most of the DNN’s parameters live in the embedding tables.' },
    { en: 'warm start', es: 'arranque en caliente',
      def: 'Empezar el entrenamiento desde los pesos del modelo anterior en vez de desde cero. Ahorra tiempo; no sirve si cambia el espacio de features.',
      say: 'We warm-start daily from yesterday’s model and retrain from scratch when features change.' },
    { en: 'contextual targeting', es: 'segmentación contextual',
      def: 'Elegir anuncios por el contenido y el contexto de la página (sección, hora, dispositivo), sin datos de la persona.',
      say: 'Without consent we fall back to contextual targeting.' },
    { en: 'first-party data', es: 'datos propios',
      def: 'Datos que el medio recoge directamente de su audiencia (qué secciones lee), a diferencia de los de terceros. Personalizar con ellos requiere consentimiento.',
      say: 'Interests come from first-party reading history, only with consent.' },
    { en: 'budget-split experiment', es: 'experimento con presupuesto dividido',
      def: 'A/B en el que el presupuesto de cada campaña se parte por brazo, en proporción al tráfico, para que los brazos no se roben gasto entre sí.',
      say: 'We run ranking changes as budget-split experiments to avoid cannibalization.' },
    { en: 'position effect', es: 'efecto de posición',
      def: 'Cuánto cambia el CTR solo por el slot. Con el supuesto separable, el modelo suma un término por slot al logit, que con CTRs chicos equivale a multiplicar la probabilidad por un factor.',
      say: 'The model learns a per-slot term, and the randomized exploration traffic checks it.' },
    { en: 'smoothed CTR', es: 'CTR suavizado',
      def: 'CTR con un prior: (clics + α) ÷ (impresiones + α + β), para que un anuncio con pocos datos no tenga un CTR extremo por azar.',
      say: 'The fallback ranks by bid times smoothed CTR.' },
    { en: 'overdelivery', es: 'sobreentrega',
      def: 'Gasto o impresiones de una campaña por encima de lo contratado (presupuesto o tope). En CPC viene de clics que llegan después de agotarse el presupuesto.',
      say: 'Overdelivery comes from clicks on impressions served before the budget ran out.' },
    { en: 'ad load', es: 'carga publicitaria',
      def: 'Cuántos anuncios ve una persona por página o por sesión. Más carga sube el ingreso de corto plazo y puede bajar el engagement.',
      say: 'Ad load is a product decision with an engagement guardrail.' },
    { en: 'ad fatigue', es: 'fatiga publicitaria',
      def: 'El CTR de un anuncio baja cada vez que la misma persona lo vuelve a ver. Se modela con las impresiones previas de esa campaña para esa persona; aquí, el contador del tope de frecuencia, leído antes de sumar la impresión actual.',
      say: 'We model ad fatigue with today’s impression count per campaign, which the frequency-cap lookup already returns.' },
    { en: 'beacon', es: 'señal de seguimiento',
      def: 'Petición chica que la página manda para registrar un evento sin esperar nada de vuelta; aquí, la impresión visible con su token firmado. Se deduplica por impresión y se vigila su tasa: si cae, faltan negativos en el training set.',
      say: 'The page sends a viewability beacon with the impression token.' },
    { en: 'MGET', es: 'lectura de varias llaves',
      def: 'Comando de Redis que lee muchas llaves en un solo viaje de red. En Redis Cluster solo funciona si todas las llaves caen en el mismo hash slot (la partición de llaves del cluster, nada que ver con los slots de anuncios): para eso está el hash tag.',
      say: 'One MGET returns the user’s caps for every candidate campaign.' },
    { en: 'hash tag (Redis Cluster)', es: 'etiqueta de hash',
      def: 'La parte de una llave entre llaves, como <code>{user}</code> en <code>fc:{user}:campaña:día</code>. Redis Cluster calcula el hash slot solo con esa parte, así que todas las llaves de una persona caen en el mismo shard y se leen con un solo MGET.',
      say: 'The user id is the hash tag, so all of a user’s cap keys live on one shard.' },
    // Chips: definidos antes en otras páginas (gana su definición); se repiten con la misma grafía.
    { en: 'negative downsampling', es: 'submuestreo de negativos',
      def: 'Entrenar con todos los positivos y una fracción de los negativos.',
      say: 'We keep every click and five percent of the non-clicks, and correct the probabilities before serving.' },
    { en: 'position bias', es: 'sesgo de posición',
      def: 'Lo de arriba recibe más interacción por estar arriba.',
      say: 'The top banner gets clicks for its position, so the slot is a feature and we serve at a reference position.' },
    { en: 'isotonic regression', es: 'regresión isotónica',
      def: 'Calibración monótona no paramétrica.',
      say: 'An isotonic calibrator fitted on a fresh day ships with every model.' },
    { en: 'calibration (ECE)', es: 'calibración (ECE)',
      def: 'Qué tanto coinciden las probabilidades predichas con las frecuencias observadas.',
      say: 'ECE looks tiny with CTRs this low, so we report the observed-to-expected ratio per bucket.' },
    { en: 'inverse propensity scoring (IPS)', es: 'puntaje por propensión inversa',
      def: 'Estimar el valor de una política con datos de otra, pesando por 1 ÷ propensity.',
      say: 'We run per-slot IPS on the exploration slice to screen policies before an A/B test.' },
    { en: 'attribution window', es: 'ventana de atribución',
      def: 'Cuánto tiempo después de una impresión un evento cuenta para ella.',
      say: 'A click counts if it arrives within a thirty-minute attribution window.' },
    { en: 'novelty effect', es: 'efecto novedad',
      def: 'Un cambio atrae interacción por ser nuevo y el efecto se desvanece.',
      say: 'New creatives get novelty clicks, so we run ad experiments for at least two weeks.' },
    { en: 'load shedding', es: 'descarte de carga',
      def: 'Rechazar trabajo a propósito cuando no hay capacidad.',
      say: 'Under overload we shed ad requests to programmatic instead of making the page wait.' },
  ];

